function status(s){if(!match(s.draft))return 'pending';if(s.confirmed!==canonical(s.draft))return 'unconfirmed';return s.candidate===match(s.draft)?'generated':'ready';}
function update(s,path,value){if(typeof value!=='string'||value.length>1800||path.some(x=>['__proto__','constructor','prototype'].includes(String(x))))throw Error('字段无效');let o=s.draft;for(const k of path.slice(0,-1)){if(!Object.hasOwn(o,k))throw Error('字段不存在');o=o[k];}let k=path.at(-1);if(!Object.hasOwn(o,k)||typeof o[k]!=='string'||k==='id')throw Error('字段不存在');if(k==='mode'&&!['A','B'].includes(value))throw Error('布局无效');if(o[k]===value)return;o[k]=value;s.confirmed=null;}
function choose(s,key){if(!['A','B'].includes(key))throw Error('未知方案');s.draft=create(key);s.confirmed=null;}
function confirm(s){s.confirmed=canonical(s.draft);}
function generate(s){let key=match(s.draft);if(!key||s.confirmed!==canonical(s.draft))throw Error('本方案尚无对应结果，请导出当前方案；页面不联网生图。');s.candidate=key;return key;}
function adopt(s){const key=match(s.draft);if(!key||s.candidate!==key||s.confirmed!==canonical(s.draft))throw Error('候选不对应当前已确认方案');if(s.adopted?.key===key)return;s.editions??={};if(s.adopted)s.editions[s.adopted.key]=clone(s.adopted.letters);s.adopted={key,signature:canonical(create(key)),letters:clone(s.editions[key]||layout(key).texts)};}
function sameShape(o,t){if(typeof t==='string')return typeof o==='string'&&o.length<=1800;if(Array.isArray(t))return Array.isArray(o)&&o.length===t.length&&o.every((v,i)=>sameShape(v,t[i]));if(!o||typeof o!=='object'||Object.keys(o).length!==Object.keys(t).length)return false;return Object.keys(t).every(k=>Object.hasOwn(o,k)&&sameShape(o[k],t[k]));}
