function compile(p){let l=layout(p.mode);return `生成一张全新、完整的黑白页漫无字底图，竖版2:3，1024×1536构图坐标。不要修改参考页后复用原排版，要按本次先验草图重新导演。\n\n输入职责：图1是本次先验布局，格线与画幅区域为主要几何约束；图2是公共角色场景道具参考，只继承身份与设计，不继承彩色插图风格或排版；图3只继承黑白漫画线条/网点风格与身份补充，不继承它的排版。图1中的中文、数字、浅色块、椭圆只是规划标记，成图绝不画这些标记，不画气泡。\n\n【1 故事理解】\n原文：${p.story.source}\n标题（后期加入，底图不画字）：${p.story.title}\n本页理解：${p.story.understanding}\n本页目的：${p.story.purpose}\n情绪变化：${p.story.emotion}\n必须保留：${p.story.mustKeep}\n\n【2 公共约束】\n小满：${p.characters.xiaoman}\n周叔：${p.characters.zhou}\n场景：${p.setting.place}\n道具：${p.setting.prop}\n画风：${p.setting.style}\n\n【3 本场状态】\n时间：${p.scene.time}\n天气：${p.scene.weather}\n连续性：${p.scene.continuity}\n禁止：${p.scene.exclude}\n\n【4 逐格脚本】\n${p.scripts.map((s,i)=>`${i+1} / ${s.beat}\n动作：${s.action}\n景别：${s.shot}\n后期文字语义（底图不画任何字和气泡）：${s.dialogue}`).join('\n\n')}\n\n【5 先验布局 ${p.mode}】\n导演意图：${l.intent}\n视觉重点：${l.focus}\n必须只有六格，不是均匀网格。阅读顺序1→2→3→4→5→6，先左到右，再上到下。画布左上为原点。六格矩形坐标(x,y,w,h)：\n${l.panels.map((b,i)=>`${i+1} ${b.name}：${b.x},${b.y},${b.w},${b.h}`).join('\n')}\n环境格面积约${Math.round(l.panels[0].w*l.panels[0].h/(1024*1536)*100)}%；递伞格约${Math.round(l.panels[4].w*l.panels[4].h/(1024*1536)*100)}%。第5格必须是手和合伞的近景，不能变成人物全身格。\n\n【6 气泡留白规划】\n${l.texts.filter(t=>['thought','dialogue'].includes(t.type)).map(t=>`${t.name}计划范围(${t.x},${t.y},${t.w},${t.h})：预留低细节区，人物面孔与关键手部避开；此时画自然连续背景，不画椭圆、气泡、文字和白色气泡洞。`).join('\n')}\n上边保留标题白边。小满与周叔的鞋子和手不得意外越框；保留白沟。所有文字、对白、拟声和标题将在HTML中独立叠加。不要任何字、气泡、格号、UI、水印，不画成规划示意。\n\n【7 自检优先级】\n六格几何及阅读顺序→本页剧情事实→身份/道具/真实握伞→手部近景→独立气泡预留。若无法完全符合，不得新增格或复制旧版式。`;}
const api={create,initial,layout,canonical,match,status,update,choose,confirm,generate,adopt,restore,compile};if(typeof module!=='undefined')module.exports=api;else root.DirectorModel=api;
